(()=>{"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const isEn=()=>document.documentElement.lang==="en"||document.documentElement.dir==="ltr",t=(he,en)=>isEn()?en:he;
async function api(path,opts={}){const init={credentials:"same-origin",...opts,headers:{...(opts.headers||{})}};if(opts.body&&!(opts.body instanceof FormData)){init.headers["Content-Type"]="application/json";init.body=JSON.stringify(opts.body)}const r=await fetch(path,init),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||t("הפעולה לא הושלמה","Action failed"));return d}
function dialog(){let d=$("#navigation-admin-dialog");if(!d){d=document.createElement("dialog");d.id="navigation-admin-dialog";d.className="modal modal-wide";document.body.append(d)}return d}
function toast(msg,bad=false){let x=$("#navigation-toast");if(!x){x=document.createElement("div");x.id="navigation-toast";x.setAttribute("role","status");x.style.cssText="position:fixed;z-index:100003;left:50%;bottom:18px;transform:translateX(-50%);padding:12px 16px;border-radius:12px;color:#fff;background:#173a4d";document.body.append(x)}x.style.background=bad?"#8f1d27":"#173a4d";x.textContent=msg;x.hidden=false;clearTimeout(x._t);x._t=setTimeout(()=>x.hidden=true,3000)}
function runNavigationAction(href){
 if(href==="#action:support"){document.getElementById("support-form-button")?.click();return true}
 if(href==="#action:accessibility"){document.querySelector("[data-open-accessibility-statement]")?.click();return true}
 if(href==="#action:add-gmach"){document.querySelector("[data-footer-add-gmach]")?.click();return true}
 if(href==="#action:add-item"){document.querySelector("[data-footer-add-item]")?.click();return true}
 if(href.startsWith("#info:")){document.querySelector('[data-open-info="'+CSS.escape(href.slice(6))+'"]')?.click();return true}
 return false
}
async function applyPublicLinks(){
 try{
  const x=await api("/api/navigation-links"),groups={footer_find:document.querySelector(".footer-links>div:nth-child(1)"),footer_share:document.querySelector(".footer-links>div:nth-child(2)"),footer_info:document.querySelector(".footer-links>div:nth-child(3)")},byLocation=new Map();
  for(const l of x.links||[]){if(!byLocation.has(l.location))byLocation.set(l.location,[]);byLocation.get(l.location).push(l)}
  for(const [location,host] of Object.entries(groups)){if(!host)continue;const links=byLocation.get(location)||[];if(!links.length)continue;[...host.children].filter(n=>n.tagName!=="STRONG").forEach(n=>{if(!n.dataset.navigationOriginal){n.dataset.navigationOriginal="1";n.hidden=true}});host.querySelectorAll("[data-dynamic-navigation]").forEach(n=>n.remove());for(const l of links){const a=document.createElement("a");a.dataset.dynamicNavigation="1";a.textContent=isEn()&&l.labelEn?l.labelEn:l.labelHe;a.href=l.href;if(l.openNewTab){a.target="_blank";a.rel="noopener"}a.addEventListener("click",e=>{if(runNavigationAction(l.href)){e.preventDefault()}});host.append(a)}}
 }catch{}
}
async function openAdmin(){
 const d=dialog();d.innerHTML='<button class="dialog-close" type="button">×</button><h2>'+t("ניהול קישורים ותפריטים","Navigation and menu management")+'</h2><div id="navigation-admin-body"></div>';$(".dialog-close",d).onclick=()=>d.close();d.showModal();
 const body=$("#navigation-admin-body",d);
 async function render(){body.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";try{const x=await api("/api/admin/navigation-links");body.innerHTML='<form id="nav-create" class="form-grid"><label>'+t("תווית בעברית","Hebrew label")+'<input name="labelHe" required></label><label>English<input name="labelEn"></label><label>URL<input name="href" required></label><label>'+t("מיקום","Location")+'<select name="location"><option>header</option><option>footer_find</option><option>footer_share</option><option>footer_info</option><option>account</option></select></label><label>'+t("סדר","Order")+'<input name="sortOrder" type="number" min="0" max="9999" value="100"></label><label><input name="enabled" type="checkbox" checked> '+t("פעיל","Enabled")+'</label><label><input name="requiresAuth" type="checkbox"> '+t("רק למשתמש מחובר","Signed-in only")+'</label><label><input name="newTab" type="checkbox"> '+t("פתיחה בטאב חדש","Open in new tab")+'</label><button class="button button-primary">'+t("הוספת קישור","Add link")+'</button></form><div style="display:grid;gap:8px;margin-top:14px">'+(x.links||[]).map(l=>'<article class="dashboard-row" data-nav-row="'+esc(l.id)+'"><div><strong>'+esc(l.labelHe)+(l.labelEn?' / '+esc(l.labelEn):'')+'</strong><p>'+esc(l.href)+'</p><small>'+esc(l.location)+' · '+l.sortOrder+' · '+(l.enabled?t("פעיל","enabled"):t("כבוי","disabled"))+'</small></div><div class="dashboard-row-actions"><button class="button button-secondary button-small" data-toggle-nav="'+esc(l.id)+'" data-enabled="'+(l.enabled?"1":"0")+'">'+(l.enabled?t("השבתה","Disable"):t("הפעלה","Enable"))+'</button><button class="button button-danger button-small" data-delete-nav="'+esc(l.id)+'">'+t("מחיקה","Delete")+'</button></div></article>').join("")+'</div>';
 const f=$("#nav-create",d);f.onsubmit=async e=>{e.preventDefault();try{await api("/api/admin/navigation-links",{method:"POST",body:{labelHe:f.labelHe.value,labelEn:f.labelEn.value,href:f.href.value,location:f.location.value,sortOrder:Number(f.sortOrder.value||0),enabled:f.enabled.checked,requiresAuth:f.requiresAuth.checked,openNewTab:f.newTab.checked}});toast(t("הקישור נוסף","Link added"));await render();await applyPublicLinks()}catch(err){toast(err.message,true)}};
 $$("[data-toggle-nav]",d).forEach(b=>b.onclick=async()=>{try{await api("/api/admin/navigation-links/"+encodeURIComponent(b.dataset.toggleNav),{method:"PATCH",body:{enabled:b.dataset.enabled!=="1"}});await render();await applyPublicLinks()}catch(e){toast(e.message,true)}});
 $$("[data-delete-nav]",d).forEach(b=>b.onclick=async()=>{if(!confirm(t("למחוק את הקישור?","Delete this link?")))return;try{await api("/api/admin/navigation-links/"+encodeURIComponent(b.dataset.deleteNav),{method:"DELETE",body:{}});await render();await applyPublicLinks()}catch(e){toast(e.message,true)}})
 }catch(e){body.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await render()
}
function installAdminButton(){const tab=$("#admin-tab"),actions=$("#dashboard-view .dashboard-actions");if(!tab||tab.hidden||!actions||actions.querySelector("[data-navigation-admin]"))return;const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.navigationAdmin="1";b.textContent=t("קישורים ותפריטים","Navigation");b.onclick=openAdmin;actions.prepend(b)}
function init(){applyPublicLinks();const o=new MutationObserver(()=>installAdminButton());o.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:["hidden","lang","dir"]});installAdminButton()}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();